import{triggers,actionTypes,comparisons,validateRules,ruleSummary,ruleIssues}from'./event-rules.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const options=(items,value)=>items.map(([key,label])=>`<option value="${esc(key)}" ${key===value?'selected':''}>${esc(label)}</option>`).join('');
export function mountRuleList(el,project,{onChange=()=>{},beforeChange=()=>{},notify=()=>{},defaultObjectId}={}){function changed(){onChange();render()}function render(){el.innerHTML=`<div class="rules-heading"><div><h3>Game events</h3><p>Choose what happens, and when.</p></div><button class="primary" id="add-rule">+ Event</button></div><div class="rules-list">${(project.rules||[]).map((r,i)=>`<div class="rule-row"><label title="Enable this event"><input type="checkbox" data-rule-enabled="${i}" ${r.enabled!==false?'checked':''} aria-label="Enable ${esc(r.name||'event '+(i+1))}"></label><button class="rule-summary" data-edit-rule="${i}"><strong>${esc(r.name||ruleSummary(r,project))}</strong>${r.name?`<span>${esc(ruleSummary(r,project))}</span>`:''}${ruleIssues(r,project).length?'<span class="rule-warning">Needs attention: '+esc(ruleIssues(r,project)[0])+'</span>':''}${r.guards?.length?'<span>Only if conditions match</span>':''}</button><button data-copy-rule="${i}" aria-label="Duplicate event ${i+1}" title="Duplicate event">⧉</button><button data-remove-rule="${i}" aria-label="Remove event ${i+1}" title="Remove event">×</button></div>`).join('')||'<p class="rules-empty">Start with a timer, key press, touch, or object click.</p>'}</div><details class="saved-action-groups"><summary>Saved actions <span>Reuse a sequence in several events</span></summary>${(project.actionGroups||[]).map((g,i)=>`<div class="rule-group"><button data-edit-group="${i}">${esc(g.name)}</button><button data-remove-group="${i}" aria-label="Remove ${esc(g.name)}">×</button></div>`).join('')}<button id="add-rule-group">+ Save an action group</button></details>`;el.querySelector('#add-rule').onclick=()=>openEditor();el.querySelector('#add-rule-group').onclick=()=>openEditor(undefined,true);el.querySelectorAll('[data-edit-rule]').forEach(b=>b.onclick=()=>openEditor(+b.dataset.editRule));el.querySelectorAll('[data-edit-group]').forEach(b=>b.onclick=()=>openEditor(+b.dataset.editGroup,true));el.querySelectorAll('[data-rule-enabled]').forEach(b=>b.onchange=()=>{beforeChange();project.rules[+b.dataset.ruleEnabled].enabled=b.checked;changed()});el.querySelectorAll('[data-copy-rule]').forEach(b=>b.onclick=()=>{beforeChange();const copy=structuredClone(project.rules[+b.dataset.copyRule]);copy.id=crypto.randomUUID();copy.name=(copy.name||'Event')+' copy';project.rules.push(copy);changed()});el.querySelectorAll('[data-remove-rule]').forEach(b=>b.onclick=()=>{beforeChange();project.rules.splice(+b.dataset.removeRule,1);changed()});el.querySelectorAll('[data-remove-group]').forEach(b=>b.onclick=()=>{const group=project.actionGroups[+b.dataset.removeGroup];if([...(project.rules||[]),...(project.actionGroups||[])].some(r=>r.actions?.some(a=>a.type==='group'&&a.groupId===group.id))){notify('This action group is used by an event. Change that event before removing the group.');return}beforeChange();project.actionGroups.splice(+b.dataset.removeGroup,1);changed()})}
 function openEditor(index,isGroup=false){const existing=(isGroup?project.actionGroups:project.rules)?.[index],draft=structuredClone(existing||{id:crypto.randomUUID(),name:'',enabled:true,when:{type:'objectclick',objectId:defaultObjectId||project.objects[0]?.id},guards:[],guardMode:'all',actions:[{type:'addvariable',variable:'Score',value:1}]}),newCounters=Object.create(null);const dialog=document.createElement('dialog');dialog.className='editor-dialog rule-editor';dialog.innerHTML=`<div class="dialog-top"><h2>${isGroup?'Saved actions':existing?'Edit event':'Create event'}</h2><button type="button" id="close-rule" aria-label="Close event editor">×</button></div><form id="rule-form"><label>${isGroup?'Action group name':'Event name (optional)'}<input id="rule-name" maxlength="${isGroup?60:80}" value="${esc(draft.name)}" placeholder="${isGroup?'Open the door':'For example: collect a key'}" ${isGroup?'required':''}></label>${isGroup?'':'<section class="rule-section"><h3><span>1</span> When</h3><label>Start this event when<select id="rule-trigger"></select></label><div id="rule-trigger-fields"></div></section><section class="rule-section"><h3><span>2</span> Only if <small>optional</small></h3><div id="rule-guards"></div><button type="button" id="add-rule-guard">+ Condition</button></section>'}<section class="rule-section"><h3><span>${isGroup?'':3}</span> Do</h3><div id="rule-actions"></div><button type="button" id="add-rule-action">+ Action</button></section><p id="rule-error" role="status"></p><footer class="rule-footer"><button type="button" id="cancel-rule">Cancel</button><button type="submit" class="primary">${isGroup?'Save actions':'Save event'}</button></footer></form>`;document.body.append(dialog);const $=s=>dialog.querySelector(s),counters=()=>Object.keys({...project.variables,...newCounters}).map(name=>[name,name]),objects=()=>project.objects.map(o=>[o.id,o.name]),sounds=()=>[...(project.sounds||[])].map(s=>[s.id,s.name]);function createCounter(select){const name=prompt('Name your counter, for example Keys found');if(!name?.trim())return;const key=name.trim();if(key.length>40||['__proto__','constructor','prototype'].includes(key)){notify('Choose another counter name, up to 40 characters.');return}if(!Object.hasOwn(project.variables||{},key))newCounters[key]=0;select(key);renderTrigger();renderGuards();renderActions()}
 function renderTrigger(){if(isGroup)return;const w=draft.when;$('#rule-trigger').innerHTML=options(Object.entries(triggers),w.type);$('#rule-trigger-fields').innerHTML=w.type==='timer'?`<div class="rule-fields"><label>After (seconds)<input data-when="seconds" type="number" min=".05" max="3600" step=".05" value="${w.seconds??1}"></label><label class="rule-check"><input data-when="repeat" type="checkbox" ${w.repeat?'checked':''}>Repeat</label></div>`:w.type==='key'?`<label>Key<input id="rule-key" readonly value="${esc((w.code||'KeyE').replace(/^Key/,''))}" aria-label="Event key" title="Click, then press the key you want"></label>`:w.type==='mouse'?`<label>Mouse button<select data-when="button">${options([['0','Left click'],['2','Right click'],['1','Middle click']],String(w.button??0))}</select></label>`:['touch','objectclick'].includes(w.type)?`<label>Object<select data-when="objectId">${options(objects(),w.objectId)}</select></label><p class="rule-help">${w.type==='objectclick'?'Only a click on this visible object will count. Objects in front block the click.':'Runs once when the player makes contact, and again after moving away and touching again.'}</p>`:w.type==='variable'?`<div class="rule-fields"><label>Counter<select data-when="variable">${options(counters(),w.variable||'Score')}</select></label><label>Comparison<select data-when="op">${options(Object.entries(comparisons),w.op||'atleast')}</select></label><label>Value<input data-when="value" type="number" value="${w.value??1}"></label></div><button type="button" id="create-trigger-counter">+ Create counter</button>`:'<p class="rule-help">Runs once each time a new game starts.</p>';dialog.querySelectorAll('[data-when]').forEach(input=>input.onchange=()=>{const key=input.dataset.when;w[key]=input.type==='checkbox'?input.checked:input.type==='number'||key==='button'?Number(input.value):input.value});$('#rule-key')?.addEventListener('focus',e=>e.target.value='Press a key…');$('#rule-key')?.addEventListener('keydown',e=>{e.preventDefault();e.stopPropagation();w.code=e.code;e.target.value=e.code.replace(/^Key/,'');e.target.blur()});$('#create-trigger-counter')?.addEventListener('click',()=>createCounter(name=>w.variable=name))}
 function renderGuards(){if(isGroup)return;$('#rule-guards').innerHTML=(draft.guards||[]).length?`<label>Conditions<select id="rule-guard-mode">${options([['all','All must match'],['any','At least one must match']],draft.guardMode||'all')}</select></label>`+draft.guards.map((g,i)=>`<div class="rule-guard"><label>Counter<select data-guard="${i}" data-key="variable">${options(counters(),g.variable)}</select></label><label>Comparison<select data-guard="${i}" data-key="op">${options(Object.entries(comparisons),g.op)}</select></label><label>Value<input data-guard="${i}" data-key="value" type="number" value="${g.value}"></label><button type="button" data-remove-guard="${i}" aria-label="Remove condition">×</button></div>`).join(''):'<p class="rule-help">No conditions. The event can always run.</p>';$('#rule-guard-mode')?.addEventListener('change',e=>draft.guardMode=e.target.value);dialog.querySelectorAll('[data-guard]').forEach(input=>input.onchange=()=>draft.guards[+input.dataset.guard][input.dataset.key]=input.dataset.key==='value'?Number(input.value):input.value);dialog.querySelectorAll('[data-remove-guard]').forEach(b=>b.onclick=()=>{draft.guards.splice(+b.dataset.removeGuard,1);renderGuards()})}
 function renderActions(){const allowed=Object.entries(actionTypes).filter(([type])=>(project.dimension==='3d'||!['tag','slide'].includes(type))&&(type!=='group'||(project.actionGroups||[]).some(g=>g.id!==draft.id)));$('#rule-actions').innerHTML=draft.actions.map((a,i)=>`<div class="rule-action"><div class="rule-action-top"><label>Action ${i+1}<select data-action-index="${i}" data-action-field="type">${options(allowed,a.type)}</select></label><button type="button" data-action-up="${i}" ${i===0?'disabled':''} aria-label="Move action earlier">↑</button><button type="button" data-action-down="${i}" ${i===draft.actions.length-1?'disabled':''} aria-label="Move action later">↓</button><button type="button" data-action-remove="${i}" ${draft.actions.length===1?'disabled':''} aria-label="Remove action">×</button></div><div class="rule-fields">${['show','hide','toggle','move'].includes(a.type)?`<label>Object<select data-action-index="${i}" data-action-field="targetId">${options(objects(),a.targetId)}</select></label>`:''}${['addvariable','setvariable'].includes(a.type)?`<label>Counter<select data-action-index="${i}" data-action-field="variable">${options(counters(),a.variable||'Score')}</select></label><label>${a.type==='addvariable'?'Amount to add':'New value'}<input type="number" data-action-index="${i}" data-action-field="value" value="${a.value??1}"></label><button type="button" data-action-counter="${i}">+ Create counter</button>`:a.type==='move'?`<label>Direction<select data-action-index="${i}" data-action-field="axis">${options([['x','Horizontal (X)'],['y',project.dimension==='3d'?'Height (Y)':'Vertical (Y)'],...(project.dimension==='3d'?[['z','Depth (Z)']]:[])],a.axis||'x')}</select></label><label>Distance (${project.dimension==='3d'?'meters':'pixels'})<input type="number" step="any" data-action-index="${i}" data-action-field="value" value="${a.value??1}"></label><label>Duration (seconds; 0 = instant)<input type="number" min="0" max="3600" step=".1" data-action-index="${i}" data-action-field="duration" value="${a.duration||0}"></label>`:a.type==='sound'?`<label>Sound<select data-action-index="${i}" data-action-field="soundId">${options([['','Choose a saved sound'],...sounds()],a.soundId)}</select></label><label class="rule-check"><input type="checkbox" data-action-index="${i}" data-action-field="loop" ${a.loop?'checked':''}>Loop as music</label>`:a.type==='stopsound'?`<label>Sound<select data-action-index="${i}" data-action-field="soundId">${options([['','All sounds and music'],...sounds()],a.soundId||'')}</select></label>`:a.type==='group'?`<label>Saved actions<select data-action-index="${i}" data-action-field="groupId">${options((project.actionGroups||[]).filter(g=>g.id!==draft.id).map(g=>[g.id,g.name]),a.groupId)}</select></label>`:a.type==='setgravity'?`<label>Gravity strength (Earth = 1)<input type="number" min="0" max="10" step=".05" data-action-index="${i}" data-action-field="value" value="${a.value??1}"></label>`:a.type==='tag'?'<p class="rule-help">Needs a tag room and another player within reach.</p>':a.type==='checkpoint'?'<p class="rule-help">The player will return here after taking damage.</p>':''}</div></div>`).join('');dialog.querySelectorAll('[data-action-index]').forEach(input=>input.onchange=()=>{const a=draft.actions[+input.dataset.actionIndex],key=input.dataset.actionField;a[key]=input.type==='checkbox'?input.checked:input.type==='number'?Number(input.value):input.value;if(key==='type'){Object.assign(a,{variable:a.variable||'Score',value:1,targetId:a.targetId||defaultObjectId||project.objects[0]?.id,axis:'x',duration:0,groupId:(project.actionGroups||[]).find(g=>g.id!==draft.id)?.id});renderActions()}});dialog.querySelectorAll('[data-action-counter]').forEach(b=>b.onclick=()=>createCounter(name=>draft.actions[+b.dataset.actionCounter].variable=name));dialog.querySelectorAll('[data-action-remove]').forEach(b=>b.onclick=()=>{draft.actions.splice(+b.dataset.actionRemove,1);renderActions()});for(const key of ['up','down'])dialog.querySelectorAll(`[data-action-${key}]`).forEach(b=>b.onclick=()=>{const i=+b.dataset[key==='up'?'actionUp':'actionDown'],j=i+(key==='up'?-1:1);[draft.actions[i],draft.actions[j]]=[draft.actions[j],draft.actions[i]];renderActions()})}
 if(!isGroup){$('#rule-trigger').onchange=e=>{draft.when={type:e.target.value,objectId:defaultObjectId||project.objects[0]?.id,seconds:1,repeat:false,code:'KeyE',button:0,variable:'Score',op:'atleast',value:1};renderTrigger()};$('#add-rule-guard').onclick=()=>{if((draft.guards||[]).length>=8)return;draft.guards??=[];draft.guards.push({variable:'Score',op:'atleast',value:1});renderGuards()}}$('#add-rule-action').onclick=()=>{if(draft.actions.length>=30)return;draft.actions.push({type:'addvariable',variable:'Score',value:1});renderActions()};$('#rule-form').onsubmit=e=>{e.preventDefault();draft.name=$('#rule-name').value.trim();const key=isGroup?'actionGroups':'rules',list=structuredClone(project[key]||[]);if(existing)list[index]=draft;else list.push(draft);const candidate={...project,[key]:list,variables:{...project.variables,...newCounters}};try{validateRules(candidate)}catch(error){$('#rule-error').textContent=error.message;return}beforeChange();project[key]=list;project.variables=candidate.variables;changed();dialog.close()};$('#close-rule').onclick=$('#cancel-rule').onclick=()=>dialog.close();dialog.onclose=()=>dialog.remove();renderTrigger();renderGuards();renderActions();dialog.showModal()}
 render();return{refresh:render}}
